<?php
// Included only after administrator authorization in evaluation.php.
$metrics = $record['metrics'] ?? [];
$source = $record['source_text'] ?? $record['document']['source_text'] ?? '';
?>
<section class="evaluation-section"><h2><?= ev_h($record['title'] ?? $record['document_title'] ?? 'Output review') ?></h2><p><?= ev_h($record['system_name'] ?? $record['system_key'] ?? $record['system'] ?? '') ?> · <?= ev_h($record['mode'] ?? '') ?> · <?= ev_h(ev_label($record['status'] ?? '')) ?></p>
<?php if (!empty($record['error_message'])): ?><p class="analytics-alert"><?= ev_h($record['error_message']) ?></p><?php endif; ?>
<?php foreach ($record['warnings'] ?? [] as $warning): ?><p class="evaluation-notice"><?= ev_h(is_string($warning) ? $warning : ($warning['message'] ?? 'Review the output validation notes.')) ?></p><?php endforeach; ?><div class="evaluation-reading"><section><h2>Source</h2><div class="evaluation-prose"><?= ev_h($source) ?></div></section><section><h2>Generated summary</h2><div class="evaluation-prose"><?= ev_h($record['summary_text'] ?? $record['summary'] ?? $record['generated_summary'] ?? '') ?></div><p class="evaluation-note"><?= (int) ($record['word_count'] ?? 0) ?> words · target <?= (int) ($record['target_words'] ?? 0) ?></p></section></div></section>
<section class="evaluation-section"><h2>Measured processing durations</h2><dl class="evaluation-meta"><?php foreach ($record['timings'] ?? [] as $phase => $duration): ?><dt><?= ev_h(ev_label($phase)) ?></dt><dd><?= ev_number($duration, 4) ?> seconds</dd><?php endforeach; ?></dl></section>
<section class="evaluation-section"><h2>Reference summaries</h2><?php foreach ($record['references'] ?? [] as $reference): ?><details><summary>Reference <?= ev_h($reference['reference_version'] ?? $reference['version'] ?? '') ?> ? <?= ev_h($reference['review_status'] ?? '') ?><?= ($reference['review_status'] ?? '') === 'approved' ? ' (used for scoring)' : ' (excluded from scoring)' ?></summary><div class="evaluation-prose"><?= ev_h($reference['text'] ?? $reference['reference_text'] ?? '') ?></div></details><?php endforeach; ?><?php if (empty($record['references'])): ?><p>No approved reference was included in this run.</p><?php endif; ?></section>
<section class="evaluation-section"><h2>Independent automatic metrics</h2><p class="evaluation-note">Factual consistency and critical-fact warnings are source-alignment heuristics. They can miss errors and raise false alarms; inspect the source before classifying a failure.</p><div class="table-wrap"><table><thead><tr><th>Metric / implementation</th><th>Value</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php foreach ($metrics as $metric): ?><tr><td><?= ev_h(ev_label($metric['name'] ?? $metric['metric_name'] ?? '')) ?><br><small><?= ev_h($metric['version'] ?? $metric['metric_version'] ?? '') ?></small></td><td class="numeric"><?= ev_number($metric['value'] ?? $metric['metric_value'] ?? null) ?></td><td><?= ev_h($metric['status'] ?? '') ?></td><td><?= ev_h($metric['error'] ?? '') ?><?php foreach (['precision', 'recall', 'f1'] as $component): if (isset($metric[$component])): ?><p><?= ev_h(ev_label($component)) ?>: <?= ev_number($metric[$component], 5) ?></p><?php endif; endforeach; ?><?php $details = ev_array($metric['details'] ?? $metric['details_json'] ?? []); foreach (['precision', 'recall', 'f1', 'total_critical_facts', 'preserved_facts', 'missing_facts', 'altered_facts', 'suspected_contradictions', 'duplicate_count', 'near_duplicate_count', 'description', 'reason', 'name', 'limitations', 'failure_reason'] as $key): if (isset($details[$key]) && is_scalar($details[$key])): ?><p><?= ev_h(ev_label($key)) ?>: <?= ev_h($details[$key]) ?></p><?php endif; endforeach; foreach ($details['warnings'] ?? [] as $warning): ?><p><?= ev_h(is_string($warning) ? $warning : ($warning['message'] ?? $warning['reason'] ?? (isset($warning['reasons']) ? implode('; ', $warning['reasons']) : ($warning['kind'] ?? 'Review required')))) ?></p><?php endforeach; ?><?php if (!empty($details['facts'])): ?><details><summary>Source-to-summary fact evidence</summary><?php foreach ($details['facts'] as $fact): ?><p><strong><?= ev_h(ev_label($fact['status'])) ?>:</strong> <?= ev_h($fact['text']) ?><br>Source: <?= ev_h($fact['source_sentence'] ?? '') ?><br>Summary: <?= ev_h($fact['matched_summary_sentence'] ?? 'No aligned sentence') ?></p><?php endforeach; ?></details><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="evaluation-section"><h2>Human content-unit verification</h2><p class="evaluation-note">Coverage is based on explicit human judgments. An unchecked unit is missing a judgment, not automatically absent from the summary.</p><?php foreach ($record['content_units'] ?? [] as $unit): ?><article class="chart-card evaluation-section"><p><?= ev_h($unit['text'] ?? $unit['unit_text'] ?? '') ?></p><?php foreach ($record['content_unit_reviews'] ?? [] as $review): if ((int) $review['unit_id'] === (int) $unit['id']): ?><p>Recorded judgment: <?= $review['represented'] ? 'Represented' : 'Not represented' ?>. <?= ev_h($review['notes']) ?></p><?php endif; endforeach; ?><?php ev_form_start('verify_unit', ['output_id' => $record['id'], 'unit_id' => $unit['id']]); ev_select('represented', 'Is this information represented?', ['1' => 'Represented', '0' => 'Not represented']); ev_input('notes', 'Evidence / reviewer notes', 'text', '', false); ev_submit('Record verification'); ?></article><?php endforeach; ?><?php if (empty($record['content_units'])): ?><p>No essential information units were defined for this source.</p><?php endif; ?></section>
<section class="evaluation-section"><h2>Error classifications</h2><ul><?php foreach ($record['errors'] ?? [] as $item): ?><li><strong><?= ev_h(ev_label($item['category'])) ?></strong>: <?= ev_h($item['notes'] ?? '') ?></li><?php endforeach; ?></ul><?php ev_form_start('classify_error', ['output_id' => $record['id']]); ev_select('category', 'Observed error category', \App\Src\Services\EvaluationService::ERROR_CATEGORIES); ev_textarea('notes', 'Evidence and source-to-summary discrepancy'); ev_submit('Save error classification'); ?></section>
<section class="evaluation-section"><h2>Submitted human assessments</h2><?php foreach ($record['ratings'] ?? [] as $rating): $scores = ev_array($rating['ratings'] ?? $rating['ratings_json'] ?? $rating); ?><article class="chart-card evaluation-section"><p>Evaluator <?= ev_h($rating['evaluator_code'] ?? 'Anonymous') ?> · <?= ev_h($rating['created_at'] ?? '') ?></p><dl class="evaluation-meta"><?php foreach (ev_criteria() as $key => [$title]): ?><dt><?= ev_h($title) ?></dt><dd><?= isset($scores[$key]) ? (int) $scores[$key] . ' / 5' : 'Not available' ?></dd><?php endforeach; ?></dl><p><?= ev_h($rating['comments'] ?? '') ?></p><details><summary>Approve a correction</summary><?php ev_form_start('correct_rating', ['rating_id' => $rating['id'], 'output_id' => $record['id']]); ev_rating_fields($scores); ev_textarea('reason', 'Required correction reason'); ev_submit('Save audited correction'); ?></details></article><?php endforeach; ?><?php if (empty($record['ratings'])): ?><p>No submitted human assessments for this output.</p><?php endif; ?></section>
